1	// SPDX-License-Identifier: Apache-2.0
2	// SPDX-FileCopyrightText: Copyright The Lance Authors
3	
4	//! # Semiring Algebra for Hyperdimensional Vectors
5	//!
6	//! Defines the [`Semiring`] trait and concrete [`HdrSemiring`] variants used
7	//! by matrix and vector operations. Each semiring pairs a multiplicative
8	//! operator (applied during inner products) with an additive monoid
9	//! (used to accumulate partial results).
10	
11	use crate::graph::blasgraph::ndarray_bridge;
12	use crate::graph::blasgraph::types::{
13	    hamming_to_similarity, BinaryOp, BitVec, HdrScalar, MonoidOp,
14	};
15	
16	/// A semiring over [`HdrScalar`] values.
17	///
18	/// The two fundamental operations are:
19	/// - **multiply** (`otimes`): combines two scalars during an inner product step.
20	/// - **add** (`oplus`): accumulates partial products into a single result.
21	///
22	/// The `zero` element is the additive identity.
23	pub trait Semiring: Send + Sync {
24	    /// The multiplicative operator.
25	    fn multiply(&self, a: &HdrScalar, b: &HdrScalar) -> HdrScalar;
26	
27	    /// The additive (accumulation) operator.
28	    fn add(&self, a: &HdrScalar, b: &HdrScalar) -> HdrScalar;
29	
30	    /// The additive identity element.
31	    fn zero(&self) -> HdrScalar;
32	
33	    /// Human-readable name of this semiring.
34	    fn name(&self) -> &str;
35	}
36	
37	/// Pre-defined semirings for hyperdimensional graph computations.
38	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
39	pub enum HdrSemiring {
40	    /// XOR multiply, majority-vote bundle add. Path composition.
41	    XorBundle,
42	    /// XOR multiply, first non-empty add. BFS traversal.
43	    BindFirst,
44	    /// Hamming distance multiply, min add. Shortest path.
45	    HammingMin,
46	    /// Similarity multiply, max add. Best match.
47	    SimilarityMax,
48	    /// XOR bind multiply, best-density add. Query expansion.
49	    Resonance,
50	    /// AND multiply, OR add. Boolean reachability.
51	    Boolean,
52	    /// XOR multiply, XOR add. GF(2) field algebra.
53	    XorField,
54	}
55	
56	impl HdrSemiring {
57	    /// Get the [`BinaryOp`] used for the multiplicative step.
58	    pub fn multiply_op(&self) -> BinaryOp {
59	        match self {
60	            HdrSemiring::XorBundle => BinaryOp::Xor,
61	            HdrSemiring::BindFirst => BinaryOp::Xor,
62	            HdrSemiring::HammingMin => BinaryOp::Xor,
63	            HdrSemiring::SimilarityMax => BinaryOp::Xor,
64	            HdrSemiring::Resonance => BinaryOp::Xor,
65	            HdrSemiring::Boolean => BinaryOp::And,
66	            HdrSemiring::XorField => BinaryOp::Xor,
67	        }
68	    }
69	
70	    /// Get the [`MonoidOp`] used for the additive accumulation.
71	    pub fn add_op(&self) -> MonoidOp {
72	        match self {
73	            HdrSemiring::XorBundle => MonoidOp::BundleMonoid,
74	            HdrSemiring::BindFirst => MonoidOp::First,
75	            HdrSemiring::HammingMin => MonoidOp::MinPopcount,
76	            HdrSemiring::SimilarityMax => MonoidOp::MinPopcount,
77	            HdrSemiring::Resonance => MonoidOp::BestDensity,
78	            HdrSemiring::Boolean => MonoidOp::Or,
79	            HdrSemiring::XorField => MonoidOp::XorField,
80	        }
81	    }
82	}
83	
84	impl Semiring for HdrSemiring {
85	    fn multiply(&self, a: &HdrScalar, b: &HdrScalar) -> HdrScalar {
86	        match self {
87	            HdrSemiring::XorBundle | HdrSemiring::BindFirst | HdrSemiring::XorField => {
88	                match (a, b) {
89	                    (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => HdrScalar::Vector(va.xor(vb)),
90	                    _ => HdrScalar::Empty,
91	                }
92	            }
93	            HdrSemiring::Resonance => match (a, b) {
94	                (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => HdrScalar::Vector(va.xor(vb)),
95	                _ => HdrScalar::Empty,
96	            },
97	            HdrSemiring::HammingMin | HdrSemiring::SimilarityMax => match (a, b) {
98	                (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => HdrScalar::Vector(va.xor(vb)),
99	                _ => HdrScalar::Empty,
100	            },
101	            HdrSemiring::Boolean => match (a, b) {
102	                (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => HdrScalar::Vector(va.and(vb)),
103	                (HdrScalar::Bool(ba), HdrScalar::Bool(bb)) => HdrScalar::Bool(*ba && *bb),
104	                _ => HdrScalar::Empty,
105	            },
106	        }
107	    }
108	
109	    fn add(&self, a: &HdrScalar, b: &HdrScalar) -> HdrScalar {
110	        // If either operand is empty, return the other.
111	        if a.is_empty() {
112	            return b.clone();
113	        }
114	        if b.is_empty() {
115	            return a.clone();
116	        }
117	
118	        match self {
119	            HdrSemiring::XorBundle => match (a, b) {
120	                (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => {
121	                    HdrScalar::Vector(BitVec::bundle(&[va, vb]))
122	                }
123	                _ => a.clone(),
124	            },
125	            HdrSemiring::BindFirst => {
