196	pub fn apply_binary_op(op: BinaryOp, a: &HdrScalar, b: &HdrScalar) -> HdrScalar {
197	    match op {
198	        BinaryOp::Xor => match (a, b) {
199	            (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => HdrScalar::Vector(va.xor(vb)),
200	            _ => HdrScalar::Empty,
201	        },
202	        BinaryOp::And => match (a, b) {
203	            (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => HdrScalar::Vector(va.and(vb)),
204	            (HdrScalar::Bool(ba), HdrScalar::Bool(bb)) => HdrScalar::Bool(*ba && *bb),
205	            _ => HdrScalar::Empty,
206	        },
207	        BinaryOp::Or => match (a, b) {
208	            (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => HdrScalar::Vector(va.or(vb)),
209	            (HdrScalar::Bool(ba), HdrScalar::Bool(bb)) => HdrScalar::Bool(*ba || *bb),
210	            _ => HdrScalar::Empty,
211	        },
212	        BinaryOp::Bundle => match (a, b) {
213	            (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => {
214	                HdrScalar::Vector(BitVec::bundle(&[va, vb]))
215	            }
216	            _ => HdrScalar::Empty,
217	        },
218	        BinaryOp::First => {
219	            if a.is_empty() {
220	                b.clone()
221	            } else {
222	                a.clone()
223	            }
224	        }
225	        BinaryOp::Second => {
226	            if b.is_empty() {
227	                a.clone()
228	            } else {
229	                b.clone()
230	            }
231	        }
232	        BinaryOp::HammingDistance => match (a, b) {
233	            (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => {
234	                HdrScalar::Float(va.hamming_distance(vb) as f32)
235	            }
236	            _ => HdrScalar::Empty,
237	        },
