239	            (HdrScalar::Vector(va), HdrScalar::Vector(vb)) => {
240	                let dist = va.hamming_distance(vb);
241	                HdrScalar::Float(hamming_to_similarity(dist))
242	            }
243	            _ => HdrScalar::Empty,
244	        },
245	        BinaryOp::FloatAdd => match (a, b) {
246	            (HdrScalar::Float(fa), HdrScalar::Float(fb)) => HdrScalar::Float(fa + fb),
247	            _ => HdrScalar::Empty,
248	        },
249	        BinaryOp::FloatMul => match (a, b) {
250	            (HdrScalar::Float(fa), HdrScalar::Float(fb)) => HdrScalar::Float(fa * fb),
251	            _ => HdrScalar::Empty,
252	        },
253	        BinaryOp::FloatMin => match (a, b) {
254	            (HdrScalar::Float(fa), HdrScalar::Float(fb)) => HdrScalar::Float(fa.min(*fb)),
255	            _ => HdrScalar::Empty,
256	        },
