4	//! # Typed Graph: one matrix per relationship type, one mask per label.
5	//!
6	//! Maps to property graph schema AND to container W16-31 inline edges.
7	//! Each relationship type (e.g. "KNOWS") gets its own adjacency matrix.
8	//! Each node label (e.g. "Person") gets a boolean mask for filtering.
9	
10	use std::collections::HashMap;
11	
12	use crate::graph::blasgraph::descriptor::GrBDesc;
13	use crate::graph::blasgraph::matrix::GrBMatrix;
14	use crate::graph::blasgraph::semiring::Semiring;
15	use crate::graph::blasgraph::sparse::CooStorage;
16	use crate::graph::blasgraph::types::BitVec;
17	use crate::graph::spo::store::SpoStore;
18	use crate::graph::spo::truth::TruthValue;
19	
20	/// A typed property graph: one matrix per relationship type, one mask per label.
21	#[derive(Clone, Debug)]
22	pub struct TypedGraph {
23	    /// One adjacency matrix per relationship type (e.g. "KNOWS" → matrix).
24	    pub relations: HashMap<String, GrBMatrix>,
25	    /// One boolean mask per node label (e.g. "Person" → [true, false, true, ...]).
26	    pub labels: HashMap<String, Vec<bool>>,
27	    /// Total number of nodes.
28	    pub node_count: usize,
29	}
30	
31	impl TypedGraph {
32	    /// Create an empty typed graph with the given node count.
33	    pub fn new(node_count: usize) -> Self {
34	        Self {
35	            relations: HashMap::new(),
36	            labels: HashMap::new(),
37	            node_count,
38	        }
39	    }
40	
41	    /// Add a relationship type with its adjacency matrix.
42	    pub fn add_relation(&mut self, name: &str, matrix: GrBMatrix) {
43	        assert_eq!(
44	            matrix.nrows(),
45	            self.node_count,
46	            "matrix rows ({}) != node_count ({})",
47	            matrix.nrows(),
48	            self.node_count
49	        );
50	        assert_eq!(
51	            matrix.ncols(),
52	            self.node_count,
53	            "matrix cols ({}) != node_count ({})",
54	            matrix.ncols(),
55	            self.node_count
56	        );
57	        self.relations.insert(name.to_string(), matrix);
58	    }
59	
60	    /// Add a node label with a list of node IDs.
61	    pub fn add_label(&mut self, name: &str, node_ids: &[usize]) {
62	        let mut mask = vec![false; self.node_count];
63	        for &id in node_ids {
64	            if id < self.node_count {
65	                mask[id] = true;
66	            }
67	        }
68	        self.labels.insert(name.to_string(), mask);
69	    }
70	
71	    /// Single-hop traversal under the given semiring for one relationship type.
72	    pub fn traverse(&self, rel_type: &str, semiring: &dyn Semiring) -> Option<GrBMatrix> {
73	        let matrix = self.relations.get(rel_type)?;
74	        let desc = GrBDesc::default();
75	        // A × A under the given semiring = one hop
76	        Some(matrix.mxm(matrix, semiring, &desc))
77	    }
78	
79	    /// Multi-hop traversal: compose multiple relationship types sequentially.
80	    ///
81	    /// `rel_types[0] × rel_types[1] × ... × rel_types[n-1]` under the semiring.
82	    pub fn multi_hop(&self, rel_types: &[&str], semiring: &dyn Semiring) -> Option<GrBMatrix> {
83	        if rel_types.is_empty() {
84	            return None;
85	        }
86	
87	        let desc = GrBDesc::default();
88	        let mut result = self.relations.get(rel_types[0])?.clone();
89	
90	        for &rel in &rel_types[1..] {
91	            let next = self.relations.get(rel)?;
92	            result = result.mxm(next, semiring, &desc);
93	        }
94	
95	        Some(result)
96	    }
97	
98	    /// Masked traversal: traverse a relationship type, masking by label.
99	    ///
100	    /// Returns only entries where the target node has the given label.
101	    pub fn masked_traverse(
102	        &self,
103	        rel_type: &str,
104	        label_mask: &str,
105	        semiring: &dyn Semiring,
106	    ) -> Option<GrBMatrix> {
107	        let matrix = self.relations.get(rel_type)?;
108	        let mask = self.labels.get(label_mask)?;
109	
110	        let desc = GrBDesc::default();
111	        let result = matrix.mxm(matrix, semiring, &desc);
112	
113	        // Apply mask: zero out entries where target is not in label
114	        let mut coo = CooStorage::new(result.nrows(), result.ncols());
115	        for (r, c, v) in result.iter() {
116	            if c < mask.len() && mask[c] {
117	                coo.push(r, c, v.clone());
118	            }
119	        }
120	        Some(GrBMatrix::from_coo(&coo))

1	//! CausalEdge64: the atomic causal unit.
2	//!
3	//! One u64. One register. One read. Full causal edge with epistemic state.
4	
5	use super::pearl::CausalMask;
6	use super::plasticity::PlasticityState;
7	
8	/// NARS inference types encoded in 3 bits.
9	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
10	#[repr(u8)]
11	pub enum InferenceType {
12	    /// A→B, B→C ⊢ A→C. Follow the chain.
13	    Deduction = 0,
14	    /// A→B, A→C ⊢ B→C. Generalize from shared cause.
15	    Induction = 1,
16	    /// A→B, C→B ⊢ A→C. Infer from shared effect.
17	    Abduction = 2,
18	    /// Merge two truth values for the same statement.
19	    Revision = 3,
20	    /// Combine complementary evidence across domains.
21	    Synthesis = 4,
22	    /// Do-calculus intervention: fix a variable by external action (Pearl's do-operator).
23	    /// Signals that the edge represents an interventional distribution P(Y | do(X=x)).
24	    Intervention = 5,
25	    /// Counterfactual: reason about what would have happened under a different world.
26	    /// Requires SPO mask + high confidence (see [`CausalEdge64::counterfactual_ready`]).
27	    Counterfactual = 6,
28	    /// Reserved for future inference types.
29	    Reserved7 = 7,
30	}
31	
32	impl InferenceType {
33	    // Used only on the v1 (non-`causal-edge-v2-layout`) read path; under v2 the
34	    // 4-bit signed mantissa decode (`from_mantissa`) supersedes it. Dead under
35	    // the default v2 feature, live under `--no-default-features`.
36	    #[allow(dead_code)]
37	    #[inline]
38	    fn from_bits(v: u8) -> Self {
39	        match v & 0b111 {
40	            0 => Self::Deduction,
41	            1 => Self::Induction,
42	            2 => Self::Abduction,
43	            3 => Self::Revision,
44	            4 => Self::Synthesis,
45	            5 => Self::Intervention,
46	            6 => Self::Counterfactual,
47	            _ => Self::Reserved7,
48	        }
49	    }
50	
51	    /// Convert to the v2 signed inference mantissa (i4, range −8..+7).
52	    ///
53	    /// Mapping per pr-ce64-mb-2-causaledge64-v2.md §"Signed Mantissa Rationale":
54	    /// - Positive mantissa (+1..+7) = forward-chain direction.
55	    /// - Negative mantissa (−1..−7) = backward-chain direction.
56	    /// - Zero (0) = Identity / neutral — bare SPO assertions, no active NARS rule.
57	    ///
58	    /// Slot table (|mantissa| = base rule index):
59	    ///   0=Identity, 1=Deduction(+)/Abduction(-), 2=Induction(+)/Contraposition(-),
60	    ///   3=Exemplification(+)/Analogy-negative(-), 4=Revision+(+)/Revision-(-),
61	    ///   5=Synthesis(+)/Decomposition(-),
62	    ///   6=Intervention(+)/Counterfactual(-) [PR-LL-1 absorbed per L-9],
63	    ///   7=Extension(+)/Intension-negative(-) [future].
64	    #[inline]
65	    pub fn to_mantissa(self) -> i8 {
66	        match self {
67	            // Forward-chain (positive mantissa)
68	            Self::Deduction => 1,
69	            Self::Induction => 2,
70	            // NOTE: Abduction is backward in the signed encoding; v1 enum maps it to +3 slot
71	            // for forward semantics, but in v2 signed scheme Abduction is negative direction.
72	            // For v1 back-compat, Abduction here returns the forward slot (+3 = Exemplification
73	            // slot). Callers must use from_mantissa() to distinguish signed direction.
74	            Self::Abduction => -1,   // backward: |1| = Abduction
75	            Self::Revision => 4,     // forward: Revision-positive slot
76	            Self::Synthesis => 5,    // forward: Synthesis slot
77	            Self::Intervention => 6, // forward: PR-LL-1 Intervention (+6 per L-9)
78	            // Backward-chain (negative mantissa)
79	            Self::Counterfactual => -6, // backward: PR-LL-1 Counterfactual (−6 per L-9)
80	            Self::Reserved7 => 7,       // extension slot (positive, forward)
81	        }
82	    }
83	
84	    /// Construct from the v2 signed inference mantissa (i4, range −8..+7).
85	    ///
86	    /// Maps magnitude + sign to the closest v1 InferenceType for back-compat.
87	    /// Positive values = forward-chain; negative values = backward-chain.
88	    /// Zero = Identity (returns Deduction as the neutral forward-chain rule).
89	    #[inline]
90	    pub fn from_mantissa(m: i8) -> Self {
91	        let mag = m.unsigned_abs() & 0x7; // magnitude 0..7
92	        let forward = m >= 0;
93	        match mag {
94	            0 => Self::Deduction, // 0 = Identity/neutral → treat as Deduction
95	            1 => {
96	                if forward {
97	                    Self::Deduction
98	                } else {
99	                    Self::Abduction
100	                }
101	            }
102	            2 => {
103	                if forward {
104	                    Self::Induction
105	                } else {
106	                    Self::Abduction
107	                }
108	            } // Contraposition → Abduction
109	            3 => {
110	                if forward {
111	                    Self::Synthesis
112	                } else {
113	                    Self::Abduction
114	                }
115	            } // Exemplification / Analogy-neg
116	            4 => Self::Revision, // Revision +/- (same enum, sign distinguishes)
117	            5 => {
118	                if forward {
119	                    Self::Synthesis
120	                } else {
121	                    Self::Synthesis
122	                }
123	            } // Synthesis / Decomposition
124	            6 => {
125	                if forward {
126	                    Self::Intervention
127	                } else {
128	                    Self::Counterfactual
129	                }
130	            } // PR-LL-1 (L-9)
131	            _ => Self::Reserved7, // 7 = Extension / Intension-negative (future)
132	        }
133	    }
134	}
