136	/// The 64-bit causal neuron.
137	///
138	/// Layout (LSB to MSB):
139	/// ```text
140	/// [0:7]   S palette index
141	/// [8:15]  P palette index
142	/// [16:23] O palette index
143	/// [24:31] NARS frequency (u8, f = val/255)
144	/// [32:39] NARS confidence (u8, c = val/255)
145	/// [40:42] Causal mask (3 bits, Pearl's 2³)
146	/// [43:45] Direction triad (3 bits, sign(dim0) per S,P,O)
147	/// [46:48] Inference type (3 bits)
148	/// [49:51] Plasticity flags (3 bits, hot/cold per S,P,O)
149	/// [52:63] Temporal index (12 bits, 4096 time slots)
150	/// ```
151	///
152	/// `#[repr(transparent)]`: a single-`u64` newtype whose layout is GUARANTEED
153	/// identical to `u64`, so `&[CausalEdge64]` can be soundly reinterpreted as
154	/// `&[u64]` (the zero-copy `MailboxSoaView::edges_raw` borrow in
155	/// `cognitive-shader-driver`). Layout-neutral — the in-memory representation
156	/// was already a bare `u64`; this only documents and compiler-enforces it for
157	/// the reinterpret (a future second field becomes a compile error). Mirrors
158	/// the ndarray twin `ndarray::hpc::causal_diff::CausalEdge64`.
159	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
160	#[repr(transparent)]
161	pub struct CausalEdge64(pub u64);
162	
163	// Bit field positions and masks
164	const S_SHIFT: u32 = 0;
165	const P_SHIFT: u32 = 8;
166	const O_SHIFT: u32 = 16;
167	const FREQ_SHIFT: u32 = 24;
168	const CONF_SHIFT: u32 = 32;
169	const CAUSAL_SHIFT: u32 = 40;
170	const DIR_SHIFT: u32 = 43;
171	const INFER_SHIFT: u32 = 46;
172	// v1 plasticity bit position; under v2 plasticity moves to `crate::layout::PLAST_SHIFT`.
173	// Live on the v1 pack/read paths, dead under the default v2 feature.
174	#[allow(dead_code)]
175	const PLAST_SHIFT: u32 = 49;
176	const TEMPORAL_SHIFT: u32 = 52;
177	
178	const BYTE_MASK: u64 = 0xFF;
179	const BITS3_MASK: u64 = 0b111;
180	const BITS12_MASK: u64 = 0xFFF;
181	
182	impl CausalEdge64 {
183	    /// Zero edge: unknown, no evidence, no time.
184	    pub const ZERO: Self = Self(0);
185	
186	    /// Pack all fields into a CausalEdge64 (v1 signature — retained for back-compat).
187	    ///
188	    /// When `causal-edge-v2-layout` is enabled:
189	    /// - The inference parameter is packed as a 3-bit value into bits 46-48 (lower
190	    ///   3 bits of the 4-bit mantissa field). This is compatible with v2 reads via
191	    ///   `inference_mantissa()` for non-negative v1 InferenceType values (0..7).
192	    /// - Plasticity is packed at v2 PLAST_SHIFT=50 (bits 50-52), not v1 PLAST_SHIFT=49.
193	    /// - **The `temporal` parameter is IGNORED.** Bits 52-63 are reclaimed by v2 for
194	    ///   W-slot (53-58), truth-band lens (59-60), and spare (61-63); bit 52 belongs
195	    ///   to plasticity. Writing temporal into those bits would corrupt the reclaim
196	    ///   zone (see plan §6 Option F, decision L-2). Use `pack_v2()` for new code.
197	    ///
198	    /// For new code, prefer `pack_v2()` (feature `causal-edge-v2-layout`).
199	    #[inline]
200	    pub fn pack(
201	        s_idx: u8,
202	        p_idx: u8,
203	        o_idx: u8,
204	        frequency: u8,
205	        confidence: u8,
206	        causal_mask: CausalMask,
207	        direction: u8,
208	        inference: InferenceType,
209	        plasticity: PlasticityState,
210	        temporal: u16,
211	    ) -> Self {
212	        let mut v: u64 = 0;
213	        v |= (s_idx as u64) << S_SHIFT;
214	        v |= (p_idx as u64) << P_SHIFT;
215	        v |= (o_idx as u64) << O_SHIFT;
216	        v |= (frequency as u64) << FREQ_SHIFT;
217	        v |= (confidence as u64) << CONF_SHIFT;
218	        v |= ((causal_mask as u64) & BITS3_MASK) << CAUSAL_SHIFT;
219	        v |= ((direction as u64) & BITS3_MASK) << DIR_SHIFT;
220	        // v2 layout: write the signed mantissa (4 bits, bits 46-49) via the
221	        // enum→mantissa mapping so that subsequent reads via inference_mantissa()
222	        // + InferenceType::from_mantissa() round-trip the *semantic* meaning.
223	        // Writing the raw enum discriminant into 3 bits would silently re-route
224	        // Abduction(2) as Induction(+2), Revision(3) as Synthesis(+3), etc.
225	        #[cfg(feature = "causal-edge-v2-layout")]
226	        {
227	            let mantissa_raw = (inference.to_mantissa() as u8) as u64 & 0xF;
228	            v |= mantissa_raw << INFER_SHIFT;
229	            v |= ((plasticity.bits() as u64) & BITS3_MASK) << crate::layout::PLAST_SHIFT;
230	            // v2: temporal is IGNORED. Bits 52-63 are reclaimed for plasticity[2]
231	            // + W-slot + truth + spare per plan §6 Option F / L-2. Writing the
232	            // v1 temporal here would corrupt the reclaim zone; silently drop it.
233	            let _ = temporal;
234	        }
235	        #[cfg(not(feature = "causal-edge-v2-layout"))]
236	        {
237	            v |= ((inference as u8 as u64) & BITS3_MASK) << INFER_SHIFT;
238	            v |= ((plasticity.bits() as u64) & BITS3_MASK) << PLAST_SHIFT;
239	            v |= ((temporal as u64) & BITS12_MASK) << TEMPORAL_SHIFT;
240	        }
241	        Self(v)
242	    }
243	
244	    // ─── Palette Indices ────────────────────────────────────────────
245	
246	    /// Subject palette index.
247	    #[inline(always)]
248	    pub fn s_idx(self) -> u8 {
249	        (self.0 >> S_SHIFT) as u8
250	    }
251	
252	    /// Predicate palette index.
253	    #[inline(always)]
254	    pub fn p_idx(self) -> u8 {
255	        (self.0 >> P_SHIFT) as u8
256	    }
257	
258	    /// Object palette index.
259	    #[inline(always)]
260	    pub fn o_idx(self) -> u8 {
261	        (self.0 >> O_SHIFT) as u8
262	    }
263	
264	    /// Set subject palette index.
265	    #[inline]
266	    pub fn set_s_idx(&mut self, v: u8) {
267	        self.0 = (self.0 & !(BYTE_MASK << S_SHIFT)) | ((v as u64) << S_SHIFT);
268	    }
269	
270	    /// Set predicate palette index.
271	    #[inline]
272	    pub fn set_p_idx(&mut self, v: u8) {
273	        self.0 = (self.0 & !(BYTE_MASK << P_SHIFT)) | ((v as u64) << P_SHIFT);
274	    }
275	
276	    /// Set object palette index.
277	    #[inline]
278	    pub fn set_o_idx(&mut self, v: u8) {
279	        self.0 = (self.0 & !(BYTE_MASK << O_SHIFT)) | ((v as u64) << O_SHIFT);
280	    }
281	
282	    // ─── NARS Truth ─────────────────────────────────────────────────
283	
284	    /// NARS frequency as u8 (raw quantized value).
285	    #[inline(always)]
286	    pub fn frequency_u8(self) -> u8 {
287	        (self.0 >> FREQ_SHIFT) as u8
288	    }
289	
290	    /// NARS confidence as u8 (raw quantized value).
291	    #[inline(always)]
292	    pub fn confidence_u8(self) -> u8 {
293	        (self.0 >> CONF_SHIFT) as u8
294	    }
295	
296	    /// NARS frequency as f32 in [0, 1].
297	    #[inline]
298	    pub fn frequency(self) -> f32 {
299	        self.frequency_u8() as f32 / 255.0
300	    }
301	
302	    /// NARS confidence as f32 in [0, 1].
303	    #[inline]
304	    pub fn confidence(self) -> f32 {
305	        self.confidence_u8() as f32 / 255.0
306	    }
307	
308	    /// NARS expectation: c * (f - 0.5) + 0.5.
309	    #[inline]
310	    pub fn expectation(self) -> f32 {
311	        let f = self.frequency();
312	        let c = self.confidence();
313	        c * (f - 0.5) + 0.5
314	    }
315	
316	    /// Evidence weight: c / (1 - c). Returns u16::MAX if c == 255.
317	    #[inline]
318	    pub fn evidence_weight(self) -> f32 {
319	        let c = self.confidence();
320	        if c >= 0.999 {
321	            f32::MAX
322	        } else {
323	            c / (1.0 - c)
324	        }
325	    }
326	
327	    /// Set frequency (u8).
328	    #[inline]
329	    pub fn set_frequency_u8(&mut self, v: u8) {
330	        self.0 = (self.0 & !(BYTE_MASK << FREQ_SHIFT)) | ((v as u64) << FREQ_SHIFT);
331	    }
332	
333	    /// Set confidence (u8).
334	    #[inline]
335	    pub fn set_confidence_u8(&mut self, v: u8) {
336	        self.0 = (self.0 & !(BYTE_MASK << CONF_SHIFT)) | ((v as u64) << CONF_SHIFT);
337	    }
338	
339	    /// Set frequency from f32.
340	    #[inline]
341	    pub fn set_frequency(&mut self, f: f32) {
342	        self.set_frequency_u8((f.clamp(0.0, 1.0) * 255.0).round() as u8);
343	    }
344	
345	    /// Set confidence from f32.
346	    #[inline]
347	    pub fn set_confidence(&mut self, c: f32) {
348	        self.set_confidence_u8((c.clamp(0.0, 1.0) * 255.0).round() as u8);
349	    }
350	
351	    // ─── Causal Mask (Pearl's 2³) ───────────────────────────────────
352	
353	    /// The 3-bit causal projection mask.
354	    #[inline(always)]
355	    pub fn causal_mask(self) -> CausalMask {
356	        CausalMask::from_bits(((self.0 >> CAUSAL_SHIFT) & BITS3_MASK) as u8)
357	    }
358	
359	    /// Set the causal mask.
360	    #[inline]
361	    pub fn set_causal_mask(&mut self, m: CausalMask) {
362	        self.0 = (self.0 & !(BITS3_MASK << CAUSAL_SHIFT))
363	            | (((m as u8 as u64) & BITS3_MASK) << CAUSAL_SHIFT);
364	    }
365	
366	    /// Match if this edge's causal mask contains AT LEAST the bits in `query_mask`.
367	    ///
368	    /// `query_mask` is interpreted as the low 3 bits of the Pearl 2³ packing
369	    /// (S=0b100, P=0b010, O=0b001 — see [`CausalMask`]). Higher bits are ignored.
370	    ///
371	    /// This is the query-side predicate used by graph WHERE clauses to filter
372	    /// edges by causal type. For example, `query_mask = CausalMask::PO as u8`
373	    /// (`0b011`) matches every edge whose causal mask has at least the P and O
374	    /// planes active — i.e. interventional edges (`PO`) and counterfactual
375	    /// edges (`SPO`), but not pure association (`SO`).
376	    ///
377	    /// Semantics:
378	    /// - `query_mask == edge_mask`: full match
379	    /// - `query_mask` is a subset of `edge_mask`: subset match
380	    /// - `query_mask` and `edge_mask` are disjoint (sharing no required bits):
381	    ///   no match
382	    /// - `query_mask == 0` (`CausalMask::None`): matches every edge — there
383	    ///   are no required bits, so the predicate is vacuously satisfied.
384	    #[inline(always)]
385	    pub const fn matches_causal(&self, query_mask: u8) -> bool {
386	        let q = query_mask & 0b111;
387	        let edge_mask = ((self.0 >> CAUSAL_SHIFT) & BITS3_MASK) as u8;
388	        (edge_mask & q) == q
389	    }
390	
391	    /// Type-safe variant of [`Self::matches_causal`] taking a [`CausalMask`].
392	    #[inline(always)]
393	    pub fn matches_causal_mask(&self, query_mask: CausalMask) -> bool {
394	        self.matches_causal(query_mask as u8)
395	    }
396	
397	    /// Is the S-plane active in the current causal projection?
398	    #[inline(always)]
399	    pub fn s_active(self) -> bool {
400	        (self.0 >> CAUSAL_SHIFT) & 0b100 != 0
401	    }
