448	    // ─── Inference Type ─────────────────────────────────────────────
449	
450	    /// Canonical, layout-agnostic NARS inference read — the **unified accessor
451	    /// every consumer should use** (the bit-49 unification). Under the v2 layout
452	    /// it decodes the 4-bit SIGNED mantissa (bits 46-49) via `from_mantissa` (so
453	    /// the sign at bit 49 that distinguishes e.g. Intervention `+6` from
454	    /// Counterfactual `−6` is honoured); under v1 it reads the 3-bit field (bits
455	    /// 46-48). `pack(X).inference()` round-trips to `X` for all enum variants on
456	    /// both layouts. This is the non-deprecated successor to `inference_type()` —
457	    /// call sites use this instead of `inference_type()` + `#[allow(deprecated)]`.
458	    #[inline(always)]
459	    pub fn inference(self) -> InferenceType {
460	        #[cfg(feature = "causal-edge-v2-layout")]
461	        {
462	            let raw = ((self.0 >> INFER_SHIFT) & 0xF) as i8;
463	            let m = (raw << 4) >> 4; // sign-extend 4-bit → i8
464	            InferenceType::from_mantissa(m)
465	        }
466	        #[cfg(not(feature = "causal-edge-v2-layout"))]
467	        {
468	            InferenceType::from_bits(((self.0 >> INFER_SHIFT) & BITS3_MASK) as u8)
469	        }
470	    }
