473	    ///
474	    /// DEPRECATED since 0.2.0: use [`inference`](Self::inference) — the canonical
475	    /// layout-agnostic accessor (v2 decodes the 4-bit signed mantissa incl. the
476	    /// bit-49 sign; v1 reads the 3-bit field). This deprecated shim now DELEGATES
477	    /// to `inference()`, so it is behaviourally identical; the deprecation remains
478	    /// only as an API nudge to migrate call sites off the v1 name.
479	    #[deprecated(
480	        since = "0.2.0",
481	        note = "use inference() — the canonical layout-agnostic accessor (v2 \
482	                decodes the 4-bit signed mantissa incl. the bit-49 sign; v1 reads \
483	                the 3-bit field); see pr-ce64-mb-2-causaledge64-v2.md."
484	    )]
485	    #[inline(always)]
486	    pub fn inference_type(self) -> InferenceType {
487	        self.inference()
488	    }
