490	    /// Canonical inference write — the **unified setter** (bit-49). v2 writes the
491	    /// 4-bit signed mantissa via `to_mantissa` (bits 46-49, sign at 49); v1 writes
492	    /// the 3-bit field (bits 46-48). Round-trips with [`inference`](Self::inference).
493	    #[inline]
494	    pub fn set_inference(&mut self, t: InferenceType) {
495	        #[cfg(feature = "causal-edge-v2-layout")]
496	        {
497	            let raw = (t.to_mantissa() as u8) as u64 & 0xF;
498	            self.0 = (self.0 & !(0xF << INFER_SHIFT)) | (raw << INFER_SHIFT);
499	        }
500	        #[cfg(not(feature = "causal-edge-v2-layout"))]
501	        {
502	            self.0 = (self.0 & !(BITS3_MASK << INFER_SHIFT))
503	                | (((t as u8 as u64) & BITS3_MASK) << INFER_SHIFT);
504	        }
505	    }
