597	    // ─── Causal Distance ────────────────────────────────────────────
598	
599	    /// Distance between two edges, respecting causal mask.
600	    /// Only palette planes where the mask bit is set contribute to distance.
601	    /// Uses precomputed 256×256 distance matrices per plane.
602	    #[inline]
603	    pub fn causal_distance(
604	        self,
605	        other: Self,
606	        s_dm: &[u16; 256 * 256],
607	        p_dm: &[u16; 256 * 256],
608	        o_dm: &[u16; 256 * 256],
609	    ) -> u32 {
610	        let mask = self.causal_mask() as u8;
611	        let mut d = 0u32;
612	        if mask & 0b100 != 0 {
613	            d += s_dm[self.s_idx() as usize * 256 + other.s_idx() as usize] as u32;
614	        }
615	        if mask & 0b010 != 0 {
616	            d += p_dm[self.p_idx() as usize * 256 + other.p_idx() as usize] as u32;
617	        }
618	        if mask & 0b001 != 0 {
619	            d += o_dm[self.o_idx() as usize * 256 + other.o_idx() as usize] as u32;
620	        }
621	        d
622	    }
