624	    // ─── Forward Pass (BNN-style) ───────────────────────────────────
625	
626	    /// The forward pass: compose palettes + propagate truth + propagate causality.
627	    ///
628	    /// This IS the "neural network inference" — but every intermediate is
629	    /// a CausalEdge64 with full interpretability.
630	    #[inline]
631	    pub fn forward(
632	        self,
633	        weight: Self,
634	        compose_s: &[u8; 256 * 256],
635	        compose_p: &[u8; 256 * 256],
636	        compose_o: &[u8; 256 * 256],
637	    ) -> Self {
638	        // 1. Palette composition (the "multiply")
639	        let s_out = compose_s[self.s_idx() as usize * 256 + weight.s_idx() as usize];
640	        let p_out = compose_p[self.p_idx() as usize * 256 + weight.p_idx() as usize];
641	        let o_out = compose_o[self.o_idx() as usize * 256 + weight.o_idx() as usize];
642	
643	        // 2. NARS truth propagation (the "activation function")
644	        // Under v2: decode the 4-bit signed mantissa (bits 46-49) and route
645	        // through the same InferenceType variants. Without this, v2 edges
646	        // built via `with_inference_mantissa()` route as 3-bit unsigned
647	        // (e.g. -1 = 0b1111 reads as Reserved7), bypassing Abduction/
648	        // Counterfactual semantics entirely.
649	        #[cfg(feature = "causal-edge-v2-layout")]
650	        #[allow(deprecated)]
651	        // weight.inference_type() is the v1 fallback below; v2 uses mantissa
652	        let resolved_infer = InferenceType::from_mantissa(weight.inference_mantissa());
653	        #[cfg(not(feature = "causal-edge-v2-layout"))]
654	        #[allow(deprecated)]
655	        // v1 layout: 3-bit unsigned inference type is the canonical read
656	        let resolved_infer = weight.inference_type();
657	        let (f_out, c_out) = match resolved_infer {
658	            InferenceType::Deduction => {
659	                let f = self.frequency() * weight.frequency();
660	                let c = f * self.confidence() * weight.confidence();
661	                (f, c)
662	            }
663	            InferenceType::Induction => {
664	                let f = weight.frequency();
665	                let w = self.frequency() * self.confidence() * weight.confidence();
666	                (f, w / (w + 1.0))
667	            }
668	            InferenceType::Abduction => {
669	                let f = self.frequency();
670	                let w = weight.frequency() * self.confidence() * weight.confidence();
671	                (f, w / (w + 1.0))
672	            }
673	            InferenceType::Revision => {
674	                let w1 = self.evidence_weight();
675	                let w2 = weight.evidence_weight();
676	                let ws = w1 + w2;
677	                if ws < f32::EPSILON {
678	                    (0.5, 0.0)
679	                } else {
680	                    let f = (self.frequency() * w1 + weight.frequency() * w2) / ws;
681	                    let c = ws / (ws + 1.0);
682	                    (f, c)
683	                }
684	            }
685	            InferenceType::Synthesis | _ => {
686	                let f = (self.frequency() + weight.frequency()) / 2.0;
687	                let c = (self.confidence() + weight.confidence()) / 2.0;
688	                (f, c)
689	            }
690	        };
691	
692	        // 3. Causal mask: AND (only planes active in BOTH survive)
693	        let mask_out =
694	            CausalMask::from_bits((self.causal_mask() as u8) & (weight.causal_mask() as u8));
695	
696	        // 4. Temporal: latest of the two (v1 read; the pack() below drops it under v2)
697	        #[allow(deprecated)]
698	        let t_out = self.temporal().max(weight.temporal());
699	
700	        // 5. Inherit plasticity from weight (the "learned" edge)
701	        //    and direction will be recomputed from composed palette entries
702	        #[allow(deprecated)] // pack() v2 path drops temporal; resolved_infer carries v2 mantissa
703	        let result = Self::pack(
704	            s_out,
705	            p_out,
706	            o_out,
707	            (f_out.clamp(0.0, 1.0) * 255.0).round() as u8,
708	            (c_out.clamp(0.0, 1.0) * 255.0).round() as u8,
709	            mask_out,
710	            weight.direction(), // TODO: recompute from composed palette dim0 signs
711	            resolved_infer,
712	            weight.plasticity(),
713	            t_out,
714	        );
715	        // Under v2: re-stamp the signed mantissa onto the result. pack() only
716	        // writes 3 bits (v1 enum discriminant) into bits 46-48; bit 49 (the
717	        // sign bit) stays 0, so negative mantissas (Abduction, Counterfactual)
718	        // would lose their sign. Override here with the resolved value.
719	        #[cfg(feature = "causal-edge-v2-layout")]
720	        let result = result.with_inference_mantissa(resolved_infer.to_mantissa());
721	        result
722	    }
723	
724	    // ─── Learning (Evidence-Driven Plasticity) ──────────────────────
725	
726	    /// Learn from an observation: NARS revision + plasticity update.
727	    ///
728	    /// This IS reinforcement learning — but the reward signal is
729	    /// evidence accumulation, not a scalar.
730	    #[inline]
731	    pub fn learn(&mut self, observation: Self, current_time: u16) {
732	        let plast = self.plasticity();
733	
734	        // Only update planes that are HOT (plastic)
735	        if plast.s_hot() && observation.s_idx() != self.s_idx() {
736	            // Evidence disagrees with current archetype on S-plane
737	            // If confidence is high → archetype needs splitting (discovery)
738	            // For now: adopt observation's archetype if it has higher confidence
739	            if observation.confidence() > self.confidence() {
740	                self.set_s_idx(observation.s_idx());
741	            }
742	        }
743	        if plast.p_hot() && observation.p_idx() != self.p_idx() {
744	            if observation.confidence() > self.confidence() {
745	                self.set_p_idx(observation.p_idx());
746	            }
747	        }
748	        if plast.o_hot() && observation.o_idx() != self.o_idx() {
749	            if observation.confidence() > self.confidence() {
750	                self.set_o_idx(observation.o_idx());
751	            }
752	        }
753	
754	        // NARS revision: merge evidence
755	        let w1 = self.evidence_weight();
756	        let w2 = observation.evidence_weight();
757	        let ws = w1 + w2;
758	        if ws > f32::EPSILON {
759	            let f_new = (self.frequency() * w1 + observation.frequency() * w2) / ws;
760	            let c_new = ws / (ws + 1.0);
761	            self.set_frequency(f_new);
762	            self.set_confidence(c_new);
763	
764	            // Plasticity transitions based on confidence
765	            let mut new_plast = plast;
766	            if c_new > 0.9 {
767	                // High confidence: freeze all planes
768	                new_plast = PlasticityState::ALL_FROZEN;
769	            } else if c_new > 0.7 {
770	                // Moderate confidence: freeze planes with low error
771	                if observation.s_idx() == self.s_idx() {
772	                    new_plast = new_plast.freeze_s();
773	                }
774	                if observation.p_idx() == self.p_idx() {
775	                    new_plast = new_plast.freeze_p();
776	                }
777	                if observation.o_idx() == self.o_idx() {
778	                    new_plast = new_plast.freeze_o();
779	                }
780	            }
781	            self.set_plasticity(new_plast);
782	        }
783	
784	        // Update temporal index
785	        self.set_temporal(current_time);
786	    }
