821	    // ─── V2 Pack ───────────────────────────────────────────────────────
822	
823	    /// V2 pack: construct a CausalEdge64 without temporal (dropped per L-2).
824	    ///
825	    /// The 12 bits formerly used by temporal are reclaimed for W-slot (53-58),
826	    /// truth-band-lens (59-60), spare (61-63), and the mantissa expansion (46-49).
827	    /// W-slot, truth-band, spare, and inference mantissa default to zero on pack_v2.
828	    /// Set them after construction with `with_w_slot`, `with_truth`,
829	    /// `with_inference_mantissa`, `with_spare`, or `with_routing`.
830	    ///
831	    /// Note: the v1 `pack()` retains its 9-arg signature (with `temporal`) for
832	    /// back-compat and migration tests. Use `pack_v2()` for all new v2 code.
833	    #[cfg(feature = "causal-edge-v2-layout")]
834	    #[inline]
835	    pub fn pack_v2(
836	        s_idx: u8,
837	        p_idx: u8,
838	        o_idx: u8,
839	        frequency: u8,
840	        confidence: u8,
841	        causal_mask: CausalMask,
842	        direction: u8,
843	        plasticity: PlasticityState,
844	    ) -> Self {
845	        use crate::layout::{
846	            BITS3_MASK as B3, CAUSAL_SHIFT as LCA, CONF_SHIFT as LC, DIR_SHIFT as LD,
847	            FREQ_SHIFT as LF, O_SHIFT as LO, PLAST_SHIFT as LPL, P_SHIFT as LP, S_SHIFT as LS,
848	        };
849	        let mut v: u64 = 0;
850	        v |= (s_idx as u64) << LS;
851	        v |= (p_idx as u64) << LP;
852	        v |= (o_idx as u64) << LO;
853	        v |= (frequency as u64) << LF;
854	        v |= (confidence as u64) << LC;
855	        v |= ((causal_mask as u64) & B3) << LCA;
856	        v |= ((direction as u64) & B3) << LD;
857	        // inference mantissa defaults to 0 (Identity/neutral)
858	        v |= ((plasticity.bits() as u64) & B3) << LPL;
859	        // W-slot, truth-band, spare default to 0
860	        Self(v)
861	    }
862	}
