864	// ─── V2 Accessors and Builders ─────────────────────────────────────────────
865	// All gated on `#[cfg(feature = "causal-edge-v2-layout")]`.
866	// G-slot is NOT present in v2 (L-3: redundant via palette family-prefix).
867	// See pr-ce64-mb-2-causaledge64-v2.md §4 for full method semantics.
868	
869	#[cfg(feature = "causal-edge-v2-layout")]
870	impl CausalEdge64 {
871	    // ── Read Accessors ──────────────────────────────────────────────────────
872	
873	    /// Witness corpus root handle (6-bit, 0..=63). 0 = no corpus anchor.
874	    ///
875	    /// WARNING: Returns GARBAGE for non-zero v1 edges — bits 53-58 were
876	    /// temporal MSBs in v1. Apply a version gate before calling on edges
877	    /// of unknown provenance. `CausalEdge64::ZERO` returns 0 (correct default).
878	    #[inline(always)]
879	    pub fn w_slot(self) -> u8 {
880	        use crate::layout::{BITS6_MASK, W_SHIFT};
881	        ((self.0 >> W_SHIFT) & BITS6_MASK) as u8
882	    }
883	
884	    /// Inference mantissa: 4-bit signed i4, range −8..+7.
885	    ///
886	    /// sign = chain direction (+ = forward-chain, − = backward-chain).
887	    /// abs = base NARS rule index (0..7). See §"Signed Mantissa Rationale".
888	    /// `CausalEdge64::ZERO` returns 0 (neutral/identity — no NARS rule applied).
889	    ///
890	    /// Sign-extension: bits 46-49 extracted as 4-bit unsigned, then
891	    /// sign-extended to i8 via arithmetic shift: if bit 3 set, OR with 0xF0.
892	    #[inline(always)]
893	    pub fn inference_mantissa(self) -> i8 {
894	        use crate::layout::{BITS4_MASK, INFER_SHIFT};
895	        let raw = ((self.0 >> INFER_SHIFT) & BITS4_MASK) as u8;
896	        if raw & 0x8 != 0 {
897	            (raw | 0xF0) as i8
898	        } else {
899	            raw as i8
900	        }
901	    }
902	
903	    /// Chain direction extracted from mantissa sign: 1=forward, −1=backward, 0=neutral.
904	    #[inline(always)]
905	    pub fn inference_direction(self) -> i8 {
906	        let m = self.inference_mantissa();
907	        if m > 0 {
908	            1
909	        } else if m < 0 {
910	            -1
911	        } else {
912	            0
913	        }
914	    }
915	
916	    /// Base NARS rule index (0..7) extracted from mantissa magnitude.
917	    #[inline(always)]
918	    pub fn inference_rule_index(self) -> u8 {
919	        self.inference_mantissa().unsigned_abs() & 0x7
