943	    /// [`crate::layout::TrustTexture`]. Purely additive — no bits move.
944	    ///
945	    /// See [`crate::layout::CausalTopology`] for the full compatibility
946	    /// statement: wire and ordinal compatibility with `TrustTexture` are
947	    /// exact, the legacy behavioural projection onto old rows is
948	    /// intentional, but the *historical factual provenance* of old rows is
949	    /// **not** guaranteed — do not treat this as ground truth for a row
950	    /// written before this accessor existed.
951	    #[inline(always)]
952	    pub fn topology(self) -> crate::layout::CausalTopology {
