1065	    /// NOTE: No `g` parameter — G-slot is absent in v2 layout (L-3: redundant via
1066	    /// palette family-prefix + SoA partition + witness corpus root).
1067	    /// Composable: `edge.with_routing(12, TrustTexture::Solid).with_inference_mantissa(-1)`.
1068	    #[inline]
1069	    pub fn with_routing(self, w: u8, t: crate::layout::TrustTexture) -> Self {
1070	        use crate::layout::{BITS2_MASK, BITS6_MASK, TRUTH_MASK, TRUTH_SHIFT, W_MASK, W_SHIFT};
1071	        debug_assert!(w <= 63, "w_slot ({w}) out of 6-bit range");
1072	        let routing = ((w as u64 & BITS6_MASK) << W_SHIFT)
1073	            | ((t.to_bits_2() as u64 & BITS2_MASK) << TRUTH_SHIFT);
1074	        Self((self.0 & !(W_MASK | TRUTH_MASK)) | routing)
1075	    }
