31	///
32	/// One memory access. No multiply. No accumulate.
33	#[derive(Clone, Debug)]
34	pub struct AttentionTable {
35	    /// Pairwise L1 distances: k × k u16 values.
36	    pub distances: Vec<u16>,
37	    /// Palette size.
38	    pub k: usize,
39	}
