68	    /// Build from a weight palette.
69	    ///
70	    /// Computes ALL pairwise L1 distances between palette entries.
71	    /// O(k²) construction, O(1) lookup forever after.
72	    pub fn build(palette: &WeightPalette) -> Self {
73	        let k = palette.len();
74	        let mut distances = vec![0u16; k * k];
75	
76	        for i in 0..k {
77	            for j in (i + 1)..k {
78	                let d = palette.entries[i].l1(&palette.entries[j]);
79	                // Scale to u16 range
80	                let max_l1 = 17u64 * 65535; // theoretical max L1 across 17 i16 dims
81	                let scaled = ((d as u64 * 65535) / max_l1).min(65535) as u16;
82	                distances[i * k + j] = scaled;
83	                distances[j * k + i] = scaled;
84	            }
85	        }
86	
87	        AttentionTable { distances, k }
88	    }
89	
90	    /// Build with PCDVQ-weighted distances.
91	    pub fn build_weighted(palette: &WeightPalette) -> Self {
92	        let k = palette.len();
93	        let mut distances = vec![0u16; k * k];
94	
95	        for i in 0..k {
96	            for j in (i + 1)..k {
97	                let d = palette.entries[i].l1_weighted(&palette.entries[j]);
98	                let max_weighted = 20u64 * 65535 + 6 * 3 * 65535 + 10 * 65535;
99	                let scaled = ((d as u64 * 65535) / max_weighted).min(65535) as u16;
100	                distances[i * k + j] = scaled;
101	                distances[j * k + i] = scaled;
102	            }
103	        }
104	
105	        AttentionTable { distances, k }
106	    }
