114	    /// Compute attention scores for a sequence of tokens.
115	    ///
116	    /// Given query palette indices and key palette indices, returns
117	    /// the n_q × n_k attention distance matrix.
118	    ///
119	    /// This replaces Q·K^T matmul. Each score is one table lookup.
120	    pub fn attention_scores(&self, q_indices: &[u8], k_indices: &[u8]) -> Vec<u16> {
121	        let n_q = q_indices.len();
122	        let n_k = k_indices.len();
123	        let mut scores = vec![0u16; n_q * n_k];
124	
125	        for (i, &qi) in q_indices.iter().enumerate().take(n_q) {
126	            for (j, &kj) in k_indices.iter().enumerate().take(n_k) {
127	                scores[i * n_k + j] = self.distance(qi, kj);
128	            }
129	        }
130	
131	        scores
132	    }
