134	    /// Compute attention scores with early termination.
135	    ///
136	    /// For each query, only computes scores for keys where the distance
137	    /// is below threshold. This is the HIP stage of HHTL — pairs that
138	    /// are obviously distant are skipped entirely.
139	    ///
140	    /// Returns sparse (query_idx, key_idx, distance) triples.
141	    pub fn attention_sparse(
142	        &self,
143	        q_indices: &[u8],
144	        k_indices: &[u8],
145	        threshold: u16,
146	    ) -> Vec<(usize, usize, u16)> {
147	        let n_q = q_indices.len();
148	        let n_k = k_indices.len();
149	        let mut sparse = Vec::new();
150	
151	        for (i, &qi) in q_indices.iter().enumerate().take(n_q) {
152	            for (j, &kj) in k_indices.iter().enumerate().take(n_k) {
153	                let d = self.distance(qi, kj);
154	                if d < threshold {
155	                    sparse.push((i, j, d));
156	                }
157	            }
158	        }
159	
160	        sparse
161	    }
