170	    /// Build from a weight palette.
171	    ///
172	    /// For each pair (a, b): compute `palette[a].xor_bind(palette[b])`,
173	    /// then find the nearest palette entry.
174	    ///
175	    /// This precomputes all possible multi-hop attention compositions.
176	    pub fn build(palette: &WeightPalette) -> Self {
177	        let k = palette.len();
178	        let mut indices = vec![0u8; k * k];
179	
180	        for a in 0..k {
181	            for b in 0..k {
182	                let composed = palette.entries[a].xor_bind(&palette.entries[b]);
183	                // Find nearest palette entry to composed result
184	                let nearest = palette
