186	                    .iter()
187	                    .enumerate()
188	                    .min_by_key(|(_, e)| composed.l1(e))
189	                    .map(|(i, _)| i)
190	                    .unwrap_or(0);
191	                indices[a * k + b] = nearest as u8;
192	            }
193	        }
194	
195	        ComposeTable { indices, k }
