151	/// Breadth-first search using hyperdimensional vectors.
152	///
153	/// Performs a level-synchronous BFS from `source` on the adjacency matrix `adj`.
154	/// Returns a vector where entry `i` contains the XOR-bound path vector from source
155	/// to node `i` (if reachable within `max_depth` hops).
156	///
157	/// Uses the BIND_FIRST semiring: XOR multiply, first non-empty add.
158	pub fn hdr_bfs(adj: &GrBMatrix, source: usize, max_depth: usize) -> GrBVector {
159	    let n = adj.nrows();
160	    assert_eq!(n, adj.ncols(), "adjacency matrix must be square");
161	    assert!(source < n, "source out of bounds");
162	
163	    let semiring = HdrSemiring::BindFirst;
164	    let desc = GrBDesc::default();
165	
166	    // Frontier: start with the source node assigned its random vector.
167	    let mut frontier = GrBVector::new(n);
168	    frontier.set(source, BitVec::random(source as u64 + 1));
169	
170	    // Result: accumulate discovered nodes.
171	    let mut result = GrBVector::new(n);
172	    result.set(source, BitVec::random(source as u64 + 1));
173	
174	    for _depth in 0..max_depth {
175	        // Advance frontier: next = frontier * A (follow outgoing edges)
176	        let next = adj.vxm(&frontier, &semiring, &desc);
177	
178	        // Only keep newly discovered nodes (not already in result).
179	        let mut new_frontier = GrBVector::new(n);
180	        let mut any_new = false;
181	        for (idx, v) in next.iter() {
182	            if result.get(idx).is_none() {
183	                new_frontier.set(idx, v.clone());
184	                result.set(idx, v.clone());
185	                any_new = true;
186	            }
187	        }
188	
189	        if !any_new {
190	            break;
191	        }
192	        frontier = new_frontier;
193	    }
194	
195	    result
196	}
